begin;
create extension if not exists pgtap with schema extensions;
select plan(68);
insert into auth.users(id,instance_id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at) values
('33000000-0000-4000-8000-000000000001','00000000-0000-0000-0000-000000000000','authenticated','authenticated','manager4@test.invalid','',now(),'{}','{}',now(),now()),
('33000000-0000-4000-8000-000000000002','00000000-0000-0000-0000-000000000000','authenticated','authenticated','inventory4@test.invalid','',now(),'{}','{}',now(),now()),
('33000000-0000-4000-8000-000000000003','00000000-0000-0000-0000-000000000000','authenticated','authenticated','sales4@test.invalid','',now(),'{}','{}',now(),now()),
('33000000-0000-4000-8000-000000000004','00000000-0000-0000-0000-000000000000','authenticated','authenticated','inactive4@test.invalid','',now(),'{}','{}',now(),now()),
('33000000-0000-4000-8000-000000000005','00000000-0000-0000-0000-000000000000','authenticated','authenticated','admin4@test.invalid','',now(),'{}','{}',now(),now());
update public.profiles set role_id=case id when '33000000-0000-4000-8000-000000000001' then '10000000-0000-4000-8000-000000000003'::uuid when '33000000-0000-4000-8000-000000000002' then '10000000-0000-4000-8000-000000000005'::uuid when '33000000-0000-4000-8000-000000000003' then '10000000-0000-4000-8000-000000000004'::uuid when '33000000-0000-4000-8000-000000000005' then (select id from public.roles where code='SUPER_ADMIN') else '10000000-0000-4000-8000-000000000003'::uuid end,is_active=id<>'33000000-0000-4000-8000-000000000004' where id::text like '33000000%';
insert into public.branches(id,code,name,address,phone) values('42000000-0000-4000-8000-000000000001','PUR-A','Purchasing A','Test','000'),('42000000-0000-4000-8000-000000000002','PUR-B','Purchasing B','Test','000');
insert into public.financial_accounts(id,code,name,account_type,created_by) values
('43000000-0000-4000-8000-000000000001','P4-CASH','P4 Cash','CASH','33000000-0000-4000-8000-000000000005'),
('43000000-0000-4000-8000-000000000002','P4-BANK','P4 Bank','BANK','33000000-0000-4000-8000-000000000005');
insert into public.financial_account_branches(account_id,branch_id) values
('43000000-0000-4000-8000-000000000001','42000000-0000-4000-8000-000000000001'),('43000000-0000-4000-8000-000000000002','42000000-0000-4000-8000-000000000001');
insert into public.user_branches(user_id,branch_id) select u,b from (values('33000000-0000-4000-8000-000000000001'::uuid),('33000000-0000-4000-8000-000000000002'::uuid),('33000000-0000-4000-8000-000000000003'::uuid),('33000000-0000-4000-8000-000000000004'::uuid),('33000000-0000-4000-8000-000000000005'::uuid))x(u) cross join (values('42000000-0000-4000-8000-000000000001'::uuid))y(b);
insert into public.categories(id,name,slug) values('51200000-0000-4000-8000-000000000001','Purchasing Test','purchasing-test');
insert into public.units_of_measure(id,code,name,symbol,allows_decimal) values('53200000-0000-4000-8000-000000000001','P4PC','P4 Pieces','pc',false),('53200000-0000-4000-8000-000000000002','P4M','P4 Metres','m',true);
insert into public.products(id,name,category_id,unit_of_measure_id) values('56200000-0000-4000-8000-000000000001','Purchase Product','51200000-0000-4000-8000-000000000001','53200000-0000-4000-8000-000000000001'),('56200000-0000-4000-8000-000000000002','Purchase Decimal','51200000-0000-4000-8000-000000000001','53200000-0000-4000-8000-000000000002');
insert into public.product_variants(id,product_id,name,sku,is_default) values('57200000-0000-4000-8000-000000000001','56200000-0000-4000-8000-000000000001','Standard','PUR-INT',true),('57200000-0000-4000-8000-000000000002','56200000-0000-4000-8000-000000000002','Standard','PUR-DEC',true);
update public.products set status='ACTIVE' where id in('56200000-0000-4000-8000-000000000001','56200000-0000-4000-8000-000000000002');
insert into public.product_prices(variant_id,price_type,amount,effective_from) values('57200000-0000-4000-8000-000000000001','RETAIL',12,now()-interval '1 day');

set local role authenticated;select set_config('request.jwt.claims','{"sub":"33000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select ok(public.has_permission('purchases.create'),'Branch Manager can create purchases');
select is(has_function_privilege('authenticated','public.receive_purchase(uuid,uuid,text,text,jsonb)','EXECUTE'),false,'Legacy receipt RPC cannot bypass actual-cost capture');
select is(has_function_privilege('authenticated','public.post_goods_receipt(uuid,uuid,text,text,date,jsonb,jsonb)','EXECUTE'),true,'Authenticated users can post cost-aware receipts');
select lives_ok($$select public.create_supplier('Phase Four Supplier','Materials Ltd','Ama','0200000000','buy@test.invalid','Accra','Test supplier')$$,'Supplier creation works');
select is((select count(*) from public.suppliers where name='Phase Four Supplier' and supplier_code like 'SUP-%' and is_active),1::bigint,'Supplier code is generated and supplier is active');
select lives_ok($$select public.save_purchase_order(null,(select id from public.suppliers where name='Phase Four Supplier'),'42000000-0000-4000-8000-000000000001',current_date,null,'INV-EMPTY','Incomplete draft',0,0,'[]',false)$$,'An incomplete draft can be saved before products are entered');
select is((select status::text from public.purchases where supplier_invoice_number='INV-EMPTY'),'DRAFT','An empty purchase remains a draft');
select is((select count(*) from public.purchase_items where purchase_id=(select id from public.purchases where supplier_invoice_number='INV-EMPTY')),0::bigint,'An incomplete draft stores no invalid placeholder lines');
select throws_ok($$select public.save_purchase_order(null,(select id from public.suppliers where name='Phase Four Supplier'),'42000000-0000-4000-8000-000000000001',current_date,null,'INV-EMPTY-ORDER','Invalid empty order',0,0,'[]',true)$$,'P0001','Add at least one complete product line before confirming the purchase order','An empty purchase cannot be confirmed');
select lives_ok($$select public.create_purchase((select id from public.suppliers where name='Phase Four Supplier'),'42000000-0000-4000-8000-000000000001',current_date,null,'INV-100','Primary',50,20,'[{"variant_id":"57200000-0000-4000-8000-000000000001","quantity":100,"unit_cost":10,"discount_amount":0}]')$$,'Draft purchase creates');
select is((select total_amount from public.purchases where supplier_invoice_number='INV-100'),970.00::numeric,'Trusted purchase total is precise');
select is((select count(*) from public.branch_inventory where branch_id='42000000-0000-4000-8000-000000000001'),0::bigint,'Draft does not change inventory');
select is((select count(*) from public.stock_movements where movement_type='PURCHASE_RECEIPT'),0::bigint,'Draft creates no movement');
select is((select amount_paid::text||'/'||balance_due::text||'/'||payment_status::text from public.purchases where supplier_invoice_number='INV-100'),'0.00/0.00/UNPAID','Draft PO has no payable before goods arrive');
select lives_ok($$select public.order_purchase((select id from public.purchases where supplier_invoice_number='INV-100'))$$,'Purchase orders');
select is((select count(*) from public.branch_inventory where branch_id='42000000-0000-4000-8000-000000000001'),0::bigint,'Ordering does not change inventory');
select lives_ok($$select public.post_goods_receipt((select id from public.purchases where supplier_invoice_number='INV-100'),'80000000-0000-4000-8000-000000000001','DEL-1','Partial',current_date,jsonb_build_array(jsonb_build_object('purchase_item_id',(select id from public.purchase_items where purchase_id=(select id from public.purchases where supplier_invoice_number='INV-100')),'quantity',60,'actual_unit_cost',11)), '[]')$$,'Partial receipt posts with actual cost');
select is((select status::text from public.purchases where supplier_invoice_number='INV-100'),'PARTIALLY_RECEIVED','Purchase becomes partially received');
select is((select received_quantity from public.purchase_items where purchase_id=(select id from public.purchases where supplier_invoice_number='INV-100')),60.000::numeric,'Received quantity is 60');
select is((select quantity_on_hand from public.branch_inventory where branch_id='42000000-0000-4000-8000-000000000001' and variant_id='57200000-0000-4000-8000-000000000001'),60.000::numeric,'Partial receipt increases inventory only by 60');
select is((select quantity_delta from public.stock_movements where movement_type='PURCHASE_RECEIPT'),60.000::numeric,'Receipt ledger delta is positive 60');
select lives_ok($$select public.post_goods_receipt((select id from public.purchases where supplier_invoice_number='INV-100'),'80000000-0000-4000-8000-000000000001','DEL-1','Retry',current_date,'[]','[]')$$,'Duplicate receipt operation safely returns existing receipt');
select is((select quantity_on_hand from public.branch_inventory where variant_id='57200000-0000-4000-8000-000000000001'),60.000::numeric,'Duplicate receipt does not duplicate stock');
select lives_ok($$select public.post_goods_receipt((select id from public.purchases where supplier_invoice_number='INV-100'),'80000000-0000-4000-8000-000000000002','DEL-2','Final',current_date,jsonb_build_array(jsonb_build_object('purchase_item_id',(select id from public.purchase_items where purchase_id=(select id from public.purchases where supplier_invoice_number='INV-100')),'quantity',40,'actual_unit_cost',10)), '[]')$$,'Second receipt posts');
select is((select status::text from public.purchases where supplier_invoice_number='INV-100'),'RECEIVED','Purchase becomes received');
select is((select quantity_on_hand from public.branch_inventory where variant_id='57200000-0000-4000-8000-000000000001'),100.000::numeric,'Second receipt completes inventory to 100');
select is((select count(*) from public.goods_receipts where purchase_id=(select id from public.purchases where supplier_invoice_number='INV-100')),2::bigint,'Two distinct GRNs exist');

select lives_ok($$select public.create_purchase((select id from public.suppliers where name='Phase Four Supplier'),'42000000-0000-4000-8000-000000000001',current_date,null,'INV-200','Over receipt',0,0,'[{"variant_id":"57200000-0000-4000-8000-000000000001","quantity":100,"unit_cost":10,"discount_amount":0}]')$$,'Second draft creates');
select lives_ok($$select public.order_purchase((select id from public.purchases where supplier_invoice_number='INV-200'))$$,'Second purchase orders');
select throws_ok($$select public.post_goods_receipt((select id from public.purchases where supplier_invoice_number='INV-200'),'80000000-0000-4000-8000-000000000003',null,null,current_date,jsonb_build_array(jsonb_build_object('purchase_item_id',(select id from public.purchase_items where purchase_id=(select id from public.purchases where supplier_invoice_number='INV-200')),'quantity',90,'actual_unit_cost',10)),jsonb_build_array(jsonb_build_object('variant_id','57200000-0000-4000-8000-000000000001','amount',25,'scope','COMPANY')))$$,'P0001','Missing product_prices.manage permission','Unauthorized selling-price update is rejected atomically');
select is((select quantity_on_hand from public.branch_inventory where variant_id='57200000-0000-4000-8000-000000000001'),100.000::numeric,'Rejected price update does not partially post receipt stock');
select set_config('request.jwt.claims','{"sub":"33000000-0000-4000-8000-000000000005","role":"authenticated"}',true);
select lives_ok($$select public.post_goods_receipt((select id from public.purchases where supplier_invoice_number='INV-200'),'80000000-0000-4000-8000-000000000003',null,null,current_date,jsonb_build_array(jsonb_build_object('purchase_item_id',(select id from public.purchase_items where purchase_id=(select id from public.purchases where supplier_invoice_number='INV-200')),'quantity',90,'actual_unit_cost',10)),jsonb_build_array(jsonb_build_object('variant_id','57200000-0000-4000-8000-000000000001','amount',25,'scope','COMPANY')))$$,'Authorized company price update and receipt post together');
select is((select amount from public.product_prices where variant_id='57200000-0000-4000-8000-000000000001' and branch_id is null and price_type='RETAIL' and effective_to is null),25.00::numeric,'Company standard selling price updates explicitly');
select ok((select effective_to is not null from public.product_prices where variant_id='57200000-0000-4000-8000-000000000001' and branch_id is null and price_type='RETAIL' and amount=12),'Prior effective-dated selling price remains in history');
select is((select actual_unit_cost from public.goods_receipt_items gri join public.goods_receipts gr on gr.id=gri.goods_receipt_id where gr.purchase_id=(select id from public.purchases where supplier_invoice_number='INV-100') and gri.quantity_received=60),11.00::numeric,'Actual partial receipt cost is persisted separately');
select is((select receipt_value from public.goods_receipt_items gri join public.goods_receipts gr on gr.id=gri.goods_receipt_id where gr.purchase_id=(select id from public.purchases where supplier_invoice_number='INV-100') and gri.quantity_received=60),660.00::numeric,'Partial receipt value uses actual cost');
select is((select unit_cost from public.purchase_items where purchase_id=(select id from public.purchases where supplier_invoice_number='INV-100')),10.00::numeric,'Original agreed purchase-order cost is unchanged');
select is((select standard_selling_price_snapshot from public.goods_receipt_items gri join public.goods_receipts gr on gr.id=gri.goods_receipt_id where gr.purchase_id=(select id from public.purchases where supplier_invoice_number='INV-100') and gri.quantity_received=60),12.00::numeric,'Receipt preserves the standard selling price seen at receipt time');
select set_config('request.jwt.claims','{"sub":"33000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select throws_ok($$select public.post_goods_receipt((select id from public.purchases where supplier_invoice_number='INV-200'),'80000000-0000-4000-8000-000000000004',null,null,current_date,jsonb_build_array(jsonb_build_object('purchase_item_id',(select id from public.purchase_items where purchase_id=(select id from public.purchases where supplier_invoice_number='INV-200')),'quantity',20,'actual_unit_cost',10)), '[]')$$,'P0001','You cannot receive more than the remaining ordered quantity','Over-receipt is rejected');
select is((select quantity_on_hand from public.branch_inventory where variant_id='57200000-0000-4000-8000-000000000001'),190.000::numeric,'Rejected over-receipt leaves stock unchanged');
select lives_ok($$select public.record_supplier_payment((select supplier_id from public.purchases where supplier_invoice_number='INV-100'),(select id from public.purchases where supplier_invoice_number='INV-100'),'42000000-0000-4000-8000-000000000001','81000000-0000-4000-8000-000000000001',400,'BANK_TRANSFER','BANK-1',current_date,'Partial payment')$$,'Partial supplier payment records');
set local role postgres;
select is((select count(*) from public.financial_movements where operation_key='81000000-0000-4000-8000-000000000001' and movement_kind='SUPPLIER_PAYMENT' and direction='OUT'),1::bigint,'Supplier payment is linked exactly once to the financial ledger');
set local role authenticated;
select is((select amount_paid::text||'/'||balance_due::text||'/'||payment_status::text from public.purchases where supplier_invoice_number='INV-100'),'400.00/660.00/PARTIALLY_PAID','Partial payment reconciles against actual receipt cost');
select lives_ok($$select public.record_supplier_payment((select supplier_id from public.purchases where supplier_invoice_number='INV-100'),(select id from public.purchases where supplier_invoice_number='INV-100'),'42000000-0000-4000-8000-000000000001','81000000-0000-4000-8000-000000000001',400,'BANK_TRANSFER','BANK-1',current_date,'Retry')$$,'Duplicate payment safely returns existing payment');
select is((select amount_paid from public.purchases where supplier_invoice_number='INV-100'),400.00::numeric,'Duplicate payment does not change paid amount');
select throws_ok($$select public.record_supplier_payment((select supplier_id from public.purchases where supplier_invoice_number='INV-100'),(select id from public.purchases where supplier_invoice_number='INV-100'),'42000000-0000-4000-8000-000000000001','81000000-0000-4000-8000-000000000002',661,'CASH',null,current_date,null)$$,'P0001','The payment amount exceeds the outstanding balance','Overpayment is rejected');
select lives_ok($$select public.record_supplier_payment((select supplier_id from public.purchases where supplier_invoice_number='INV-100'),(select id from public.purchases where supplier_invoice_number='INV-100'),'42000000-0000-4000-8000-000000000001','81000000-0000-4000-8000-000000000003',660,'CASH','FINAL',current_date,null)$$,'Final payment records');
select is((select amount_paid::text||'/'||balance_due::text||'/'||payment_status::text from public.purchases where supplier_invoice_number='INV-100'),'1060.00/0.00/PAID','Full payment reconciles actual receipt cost');
select is((select outstanding_balance from public.supplier_balances where supplier_id=(select id from public.suppliers where name='Phase Four Supplier')),900.00::numeric,'Supplier balance includes only the partially received second PO value');
select lives_ok($$select public.reverse_supplier_payment((select id from public.supplier_payments where operation_key='81000000-0000-4000-8000-000000000003'),'Supplier issued a refund')$$,'Posted supplier payment can be reversed with an auditable reason');
select is((select sp.status||'/'||p.amount_paid::text||'/'||p.balance_due::text from public.supplier_payments sp join public.purchases p on p.id=sp.purchase_id where sp.operation_key='81000000-0000-4000-8000-000000000003'),'REVERSED/400.00/660.00','Supplier payment reversal restores the payable amount');
set local role postgres;
select is((select count(*) from public.financial_movements where reference_type='SUPPLIER_PAYMENT_REVERSAL' and reference_id=(select id from public.supplier_payments where operation_key='81000000-0000-4000-8000-000000000003') and direction='IN'),1::bigint,'Supplier payment reversal posts one compensating inflow');
set local role authenticated;

select lives_ok($$select public.create_purchase((select id from public.suppliers where name='Phase Four Supplier'),'42000000-0000-4000-8000-000000000001',current_date,null,'INV-300','Cancel',0,0,'[{"variant_id":"57200000-0000-4000-8000-000000000002","quantity":2.5,"unit_cost":20,"discount_amount":0}]')$$,'Decimal purchase draft creates');
select lives_ok($$select public.order_purchase((select id from public.purchases where supplier_invoice_number='INV-300'))$$,'Cancellable purchase orders');
select lives_ok($$select public.cancel_purchase((select id from public.purchases where supplier_invoice_number='INV-300'))$$,'Unreceived ordered purchase cancels');
select is((select status::text from public.purchases where supplier_invoice_number='INV-300'),'CANCELLED','Cancelled status is preserved');
select throws_ok($$select public.cancel_purchase((select id from public.purchases where supplier_invoice_number='INV-100'))$$,'P0001','A purchase with received goods cannot be cancelled','Received purchase cannot cancel');
select throws_ok($$update public.branch_inventory set quantity_on_hand=999$$,'42501',null,'Direct stock update remains denied');
select throws_ok($$insert into public.stock_movements(branch_id,variant_id,movement_type,quantity_delta,balance_before,balance_after,reference_type,performed_by) values('42000000-0000-4000-8000-000000000001','57200000-0000-4000-8000-000000000001','PURCHASE_RECEIPT',1,190,191,'GOODS_RECEIPT','33000000-0000-4000-8000-000000000001')$$,'42501',null,'Direct purchase movement insert is denied');

select set_config('request.jwt.claims','{"sub":"33000000-0000-4000-8000-000000000003","role":"authenticated"}',true);
select throws_ok($$select public.create_purchase((select id from public.suppliers where name='Phase Four Supplier'),'42000000-0000-4000-8000-000000000001',current_date,null,null,null,0,0,'[{"variant_id":"57200000-0000-4000-8000-000000000001","quantity":1,"unit_cost":1}]')$$,'P0001','You do not have permission to create purchases','Sales cannot create purchase');
select throws_ok($$select public.record_supplier_payment((select id from public.suppliers where name='Phase Four Supplier'),(select id from public.purchases where supplier_invoice_number='INV-200'),'42000000-0000-4000-8000-000000000001','81000000-0000-4000-8000-000000000004',1,'CASH',null,current_date,null)$$,'P0001','You do not have permission to record this payment','Sales cannot record supplier payment');
select is((select count(*) from public.purchases where branch_id='42000000-0000-4000-8000-000000000002'),0::bigint,'Cross-branch purchase read returns no rows');
select set_config('request.jwt.claims','{"sub":"33000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select throws_ok($$select public.post_goods_receipt((select id from public.purchases where supplier_invoice_number='INV-200'),'80000000-0000-4000-8000-000000000005',null,null,current_date,'[]','[]')$$,'P0001','At least one receipt item is required','Inventory role reaches authorized receiving workflow');
select throws_ok($$select public.post_goods_receipt((select id from public.purchases where supplier_invoice_number='INV-200'),'80000000-0000-4000-8000-000000000006',null,null,current_date,'[]','[]')$$,'P0001','At least one receipt item is required','Receipt validation is database authoritative');
select set_config('request.jwt.claims','{"sub":"33000000-0000-4000-8000-000000000004","role":"authenticated"}',true);
select is((select count(*) from public.purchases),0::bigint,'Inactive user cannot read purchases');
set local role anon;select set_config('request.jwt.claims','{"role":"anon"}',true);
select is((select count(*) from public.suppliers),0::bigint,'Anonymous cannot read suppliers');
set local role authenticated;select set_config('request.jwt.claims','{"sub":"33000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select is((select count(*) from public.inventory_integrity_issues()),0::bigint,'Purchase receipts preserve ledger/current reconciliation');
set local role postgres;
select ok((select count(*)>=8 from public.audit_logs where action in('supplier.created','purchase.created','purchase.ordered','purchase.goods_received','supplier_payment.recorded','purchase.cancelled')),'Purchasing business actions are audited');
select * from finish();rollback;
